    "/api/faucet/fund": {
        parameters: {
            query?: never;
            header?: never;
            path?: never;
            cookie?: never;
        };
        get?: never;
        put?: never;
        /**
         * Fund a Stellar testnet wallet via Friendbot
         * @description Funds the given Stellar account with testnet XLM using Friendbot. Enforced testnet-only: if the configured Horizon URL is not a testnet URL (HORIZON_URL env var), the request is rejected with 403. If the account already has a non-zero native balance it is not re-funded (the service still responds 200, with `success: false` in the payload). Rate limited per IP and per wallet address. The per-IP limit is configurable via FAUCET_RATE_LIMIT (defaults to 20/min in development, 5/min in production), with a fixed 60-minute window. A strict per-wallet limit of 1 request per 24 hours is enforced in Redis to prevent draining testnet XLM through rotating proxies.
         */
        post: {
            parameters: {
                query?: never;
                header?: never;
                path?: never;
                cookie?: never;
            };
            requestBody: {
                content: {
                    /**
                     * @example {
                     *       "publicKey": "GD5JQHFZLLM7H45AEB5S7M2E7EYQ3M3K5Y6R7B8C9D0E1F2G3H4I5J6K7L8M9N0O"
                     *     }
                     */
                    "application/json": {
                        /**
                         * @description Stellar public key (G...) to fund on testnet
                         * @example GD5JQHFZLLM7H45AEB5S7M2E7EYQ3M3K5Y6R7B8C9D0E1F2G3H4I5J6K7L8M9N0O
                         */
                        publicKey: string;
                    };
                };
            };
            responses: {
                /** @description Funding attempted. `data.success` is `false` (with no error status) when the account already holds a non-zero XLM balance and Friendbot was not called. */
                200: {
                    headers: {
                        [name: string]: unknown;
                    };
                    content: {
                        "application/json": {
                            /** @example true */
                            success?: boolean;
                            data?: {
                                success?: boolean;
                                message?: string;
                                fundedAmount?: string;
                                newBalance?: string;
                                currentBalance?: string;
                                transactionHash?: string;
                                ledger?: number;
                            };
                        };
                    };
                };
                /** @description Missing publicKey, or Friendbot rejected the address as invalid */
                400: {
                    headers: {
                        [name: string]: unknown;
                    };
                    content: {
                        /**
                         * @example {
                         *       "error": "Public key is required"
                         *     }
                         */
                        "application/json": components["schemas"]["Error"];
                    };
                };
                /** @description Faucet is disabled because the server is not configured for testnet */
                403: {
                    headers: {
                        [name: string]: unknown;
                    };
                    content: {
                        /**
                         * @example {
                         *       "error": "Faucet only available on testnet"
                         *     }
                         */
                        "application/json": components["schemas"]["Error"];
                    };
                };
                429: components["responses"]["TooManyRequests"];
                /** @description Unexpected error while funding the wallet */
                500: {
                    headers: {
                        [name: string]: unknown;
                    };
                    content: {
                        "application/json": components["schemas"]["Error"];
                    };
                };
                /** @description Unable to connect to the Stellar testnet Horizon server */
                503: {
                    headers: {
                        [name: string]: unknown;
                    };
                    content: {
                        /**
                         * @example {
                         *       "error": "Unable to connect to Stellar testnet"
                         *     }
                         */
                        "application/json": components["schemas"]["Error"];
                    };
                };
            };
        };
        delete?: never;
        options?: never;
        head?: never;
        patch?: never;
        trace?: never;
    };
